    rows.push(Math.abs(x0)<1e-9?"连续但不可导":"绝对值函数在非原点可导");
  }else if(si===4){
    rows.push("f(x)=x²，x₀ = "+fmt(x0,2));
    rows.push("|h| = "+fmt(Math.abs(h),4));
    rows.push("r(h)=h² = "+fmt(absErr,6));
    rows.push("r(h)/|h| = "+fmt(errRatio,6));
