    rows.push("当前高亮："+(side>0?"右侧":"左侧"));
  }else{
    rows.push("f(x)=x²，x₀ = "+fmt(x0,2));
    rows.push("h = "+(h>0?"+":"−")+fmt(Math.abs(h),3));
    rows.push("m(h) = "+fmt(slope,4));
